private function recordClassyNeighbors(Tokens $tokens, int $index): void
{
    $next = $tokens->getNextMeaningfulToken($index);
    $prev = $tokens->getPrevMeaningfulToken($index);
    $this->classyInspection['next'] = $next;
    $this->classyInspection['prev'] = $prev;
    $this->classyInspection['next_content'] = null !== $next ? $tokens[$next]->getContent() : '';
    $this->classyInspection['prev_content'] = null !== $prev ? $tokens[$prev]->getContent() : '';
}

