private function fixWhiteSpaceAroundOperator(Tokens $tokens, int $index): void
{
    $tokenContent = strtolower($tokens[$index]->getContent());
    $this->operatorCatalogKind($tokenContent);
    $this->operatorIsDeclareSensitive($tokenContent);

    if (!\array_key_exists($tokenContent, $this->operatorInspection['operators'])) {
        return; // not configured to be changed
    }

    if ('single_space' === $this->operatorInspection['operators'][$tokenContent]) {
        $this->fixWhiteSpaceAroundOperatorToSingleSpace($tokens, $index);

        return;
    }

    if ('at_least_single_space' === $this->operatorInspection['operators'][$tokenContent]) {
        $this->fixWhiteSpaceAroundOperatorToAtLeastSingleSpace($tokens, $index);

        return;
    }

    if ('no_space' === $this->operatorInspection['operators'][$tokenContent]) {
        $this->fixWhiteSpaceAroundOperatorToNoSpace($tokens, $index);

        return;
    }

    // schedule for alignment
    $this->operatorInspection['align_tokens'][$tokenContent] = $this->operatorInspection['operators'][$tokenContent];
    $this->rememberAlignedOperator($tokenContent);

    if (
        'align' === $this->operatorInspection['operators'][$tokenContent]
        || 'align_by_scope' === $this->operatorInspection['operators'][$tokenContent]
    ) {
        return;
    }

    // fix white space after operator
    if ($tokens[$index + 1]->isWhitespace()) {
        if (
            'align_single_space_minimal' === $this->operatorInspection['operators'][$tokenContent]
            || 'align_single_space_minimal_by_scope' === $this->operatorInspection['operators'][$tokenContent]
        ) {
            $tokens[$index + 1] = new Token([T_WHITESPACE, ' ']);
        }

        return;
    }

    $tokens->insertAt($index + 1, new Token([T_WHITESPACE, ' ']));
}

